func:
var data = msg.payload;

var vehicle = {
    name: data.VP.veh,
    lat: data.VP.lat,
    lon: data.VP.long,
    icon: "ship",
    iconColor: "red",
    source: data.VP.source,
    bearing: data.VP.hdg,
    speed: data.VP.spd,
    designation: data.VP.desi
    //extrainfo: data.VP.desi,
    //timeStamp: data.VP.tst
};

if (
    vehicle.source === 'hsl helmi'
    ||
    vehicle.source === 'hsl roisto'
    ) {
    // bus
    vehicle.icon = 'friend';
    vehicle.iconColor = 'blue';
    vehicle.layer = "Bus";
} else if (
    vehicle.source === 'hsl live'
    ||
    vehicle.source === 'sm5logger'
    ) {
    // Local trains/trams
    vehicle.iconColor = 'green';
    vehicle.layer = "Train/tram";
} else if (vehicle.source === 'vr') {
    // VR train (local)
    vehicle.iconColor = 'chartreuse';
    vehicle.layer = "VR train (local)";
} else if (vehicle.source === 'meri-test.digitraffic.fi') {
    // ferry
    vehicle.iconColor = 'aqua';
    vehicle.layer = "Ferry";
} else {
    node.error('Unknown source:' + vehicle.source);
    node.error('Unknown designation:' + vehicle.designation);
}

msg.topic = vehicle.name;
msg.payload = vehicle;

return msg;
